#!/usr/bin/env python3
"""Minimal OpenOCD telnet client: read target memory, halt/resume.

Used to read the LVGL HMI model (vg_model.c static s_sensors) straight out of
RAM, so the home-page point table can be checked without a screenshot.
"""

import argparse
import re
import socket
import sys
import time

PROMPT = re.compile(rb"\n?>\s*$")


class Ocd:
    def __init__(self, host, port, timeout=10.0):
        self.sock = socket.create_connection((host, port), timeout=timeout)
        self.buf = b""
        time.sleep(0.4)
        self.sock.settimeout(0.4)
        try:
            self.buf = self.sock.recv(65536)
        except socket.timeout:
            pass
        self.sock.settimeout(timeout)

    def cmd(self, text):
        self.sock.sendall(text.encode() + b"\n")
        deadline = time.time() + 15.0
        while time.time() < deadline:
            if self.buf.endswith(b"> ") or self.buf.endswith(b">"):
                break
            try:
                chunk = self.sock.recv(65536)
            except socket.timeout:
                break
            if not chunk:
                break
            self.buf += chunk
        out, self.buf = self.buf, b""
        return out.decode("utf-8", "replace")

    def read_mem(self, addr, words):
        """Read `words` 32-bit words and return the raw little-endian bytes."""
        out = self.cmd("mdw 0x%08x %d" % (addr, words))
        data = bytearray()
        for line in out.splitlines():
            if ":" not in line:
                continue
            _, _, rhs = line.partition(":")
            for tok in rhs.split():
                if re.fullmatch(r"[0-9a-fA-F]{8}", tok):
                    data += int(tok, 16).to_bytes(4, "little")
        return bytes(data)

    def read_cstr(self, addr, maxlen):
        raw = self.read_mem(addr, (maxlen + 3) // 4)
        end = raw.find(b"\x00")
        return raw[:end if end >= 0 else len(raw)].decode("utf-8", "replace")

    def close(self):
        try:
            self.sock.sendall(b"exit\n")
            self.sock.close()
        except OSError:
            pass


SENSORS_BASE = 0x2400ef18   # vg_model.c static vg_sensor_t s_sensors[64]
SENSOR_N = 0x2400ef14       # static uint16_t s_sensor_n
SENSOR_STRIDE = 768         # sizeof(vg_sensor_t): 49152 bytes / 64
NAME_OFF = 24               # char id[24] then char name[48]
ID_OFF = 0


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--port", type=int, default=4444)
    ap.add_argument("--count", type=int, default=0,
                    help="points to dump; 0 = read s_sensor_n first")
    ap.add_argument("--no-halt", action="store_true",
                    help="do not halt/resume (target already halted)")
    args = ap.parse_args()

    o = Ocd(args.host, args.port)
    try:
        if not args.no_halt:
            o.cmd("halt")
        raw_n = o.read_mem(SENSOR_N, 1)
        n = int.from_bytes(raw_n[:2], "little")
        count = args.count or n
        if count > 64:
            count = 64
        print("s_sensor_n=%d (dumping %d)" % (n, count))
        for i in range(count):
            base = SENSORS_BASE + i * SENSOR_STRIDE
            pid = o.read_cstr(base + ID_OFF, 24)
            name = o.read_cstr(base + NAME_OFF, 48)
            print("s_sensors[%02d] id=%s name=%s" % (i, pid, name))
        if not args.no_halt:
            o.cmd("resume")
    finally:
        o.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())

